-- Device delegation is separate from platform cookies and MCP credentials.
CREATE TABLE agent_proofs(digest text PRIMARY KEY,session_digest text NOT NULL REFERENCES sessions(digest) ON DELETE CASCADE,user_id text NOT NULL REFERENCES users(id),device_id text NOT NULL,origin text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE agent_grants(digest text PRIMARY KEY,session_digest text NOT NULL REFERENCES sessions(digest) ON DELETE CASCADE,user_id text NOT NULL REFERENCES users(id),device_id text NOT NULL,origin text NOT NULL,expires_at timestamptz NOT NULL);
CREATE INDEX agent_grants_device ON agent_grants(user_id,device_id);
CREATE TABLE credential_backups(id text PRIMARY KEY,owner_id text NOT NULL,project_id text NOT NULL,connection_id text NOT NULL,kind text NOT NULL CHECK(kind IN ('token','oauth','variable')),reference_id text NOT NULL,source_digest text NOT NULL,version integer NOT NULL CHECK(version>0),nonce bytea NOT NULL,ciphertext bytea NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,UNIQUE(owner_id,project_id,connection_id,kind,reference_id),FOREIGN KEY(project_id,owner_id) REFERENCES project_members(project_id,user_id) ON DELETE CASCADE,FOREIGN KEY(project_id,connection_id) REFERENCES connections(project_id,id) ON DELETE CASCADE);
